#' Summarize directed source-receptor dyads across runs
summarize_connectivity_by_dyad <- function(exchange) {
  if (!nrow(exchange)) return(data.frame()); candidate <- exchange[exchange$within_evaluation_distance, ]; groups <- split(candidate, candidate$source_receptor_id)
  sm <- function(x) if (all(is.na(x))) NA_real_ else mean(x, na.rm = TRUE); sn <- function(x, f) if (all(is.na(x))) NA_real_ else f(x, na.rm = TRUE); ss <- function(x) if (all(is.na(x))) NA_real_ else sum(x, na.rm = TRUE)
  do.call(rbind, lapply(groups, function(x) data.frame(source_id = x$source_id[1], receptor_id = x$receptor_id[1], source_receptor_id = x$source_receptor_id[1], distance_from_source_km = mean(x$distance_from_source_km), n_runs_evaluated = length(unique(x$run_id)), n_intercept_runs = length(unique(x$run_id[x$intercept])), intercept_frequency = length(unique(x$run_id[x$intercept])) / length(unique(x$run_id)), first_intercept_release_start = if (any(x$intercept)) min(x$release_start[x$intercept]) else as.POSIXct(NA, tz = "UTC"), last_intercept_release_start = if (any(x$intercept)) max(x$release_start[x$intercept]) else as.POSIXct(NA, tz = "UTC"), mean_first_arrival_hours = sm(x$first_arrival_hour[x$intercept]), minimum_first_arrival_hours = sn(x$first_arrival_hour[x$intercept], min), mean_exposure_duration_hours = sm(x$exposure_duration_hours[x$intercept]), maximum_particle_count = sn(x$particle_count_max, max), mean_particle_count_cumulative = sm(x$particle_count_cumulative), total_particle_count_cumulative = ss(x$particle_count_cumulative), total_decayed_mass_cumulative = ss(x$decayed_mass_cumulative), total_decayed_concentration_hourly_sum = ss(x$decayed_concentration_hourly_sum), stringsAsFactors = FALSE)))
}
